 static JSClassDef JSHTMLCollectionClassDefine = 
 {
     "HTMLCollection",
     .finalizer = JSHTMLCollection::finalizer,
     .gc_mark = JSHTMLCollection::mark,
+    .exotic = &js_htmlcollection_exotic,
