/* mainwindow.cpp - WatchWeb main window (circular layout)
 *
 * Copyright (C) 2026 Zhang Ji Peng
 * Contact : onecoolx@gmail.com
 */

#include "config.h"
#include "lvgl.h"

#include "mainwindow.h"
#include "webview.h"
#include "app.h"

MainWindow::MainWindow()
    : m_screen(nullptr)
    , m_bg(nullptr)
    , m_addr_bar(nullptr)
    , m_progress(nullptr)
    , m_btn_back(nullptr)
    , m_btn_forward(nullptr)
    , m_btn_reload(nullptr)
    , m_webview(nullptr)
{
}

MainWindow::~MainWindow()
{
    delete m_webview;
}

void MainWindow::create()
{
    m_screen = lv_screen_active();
    lv_obj_set_style_bg_color(m_screen, lv_color_black(), 0);

    createBackground();
    createAddressBar();
    createProgressBar();
    createContentArea();
    createNavButtons();
}

void MainWindow::createBackground()
{
    /* Circular background matching watch face */
    m_bg = lv_obj_create(m_screen);
    lv_obj_set_size(m_bg, SCREEN_WIDTH, SCREEN_HEIGHT);
    lv_obj_set_pos(m_bg, 0, 0);
    lv_obj_set_style_radius(m_bg, SCREEN_RADIUS, 0);
    lv_obj_set_style_bg_color(m_bg, lv_color_white(), 0);
    lv_obj_set_style_border_width(m_bg, 0, 0);
    lv_obj_set_style_pad_all(m_bg, 0, 0);
    lv_obj_clear_flag(m_bg, LV_OBJ_FLAG_SCROLLABLE);
}

void MainWindow::createAddressBar()
{
    /* Address bar at top of circular area */
    m_addr_bar = lv_textarea_create(m_bg);
    lv_obj_set_pos(m_addr_bar, ADDR_BAR_X, ADDR_BAR_Y);
    lv_obj_set_size(m_addr_bar, ADDR_BAR_WIDTH, ADDR_BAR_HEIGHT);
    lv_textarea_set_one_line(m_addr_bar, true);
    lv_textarea_set_placeholder_text(m_addr_bar, "Enter URL...");
    lv_obj_set_style_text_font(m_addr_bar, &lv_font_montserrat_14, 0);
    lv_obj_set_style_radius(m_addr_bar, ADDR_BAR_HEIGHT / 2, 0);
    lv_obj_set_style_bg_color(m_addr_bar, lv_color_make(240, 240, 240), 0);
    lv_obj_set_style_border_color(m_addr_bar, lv_color_make(200, 200, 200), 0);
    lv_obj_set_style_border_width(m_addr_bar, 1, 0);

    lv_obj_add_event_cb(m_addr_bar, on_addr_submit, LV_EVENT_READY, this);
}

void MainWindow::createProgressBar()
{
    /* Arc progress indicator around the edge */
    m_progress = lv_arc_create(m_bg);
    lv_obj_set_size(m_progress, SCREEN_WIDTH - 8, SCREEN_HEIGHT - 8);
    lv_obj_center(m_progress);
    lv_arc_set_rotation(m_progress, 270);
    lv_arc_set_bg_angles(m_progress, 0, 360);
    lv_arc_set_value(m_progress, 0);
    lv_obj_remove_style(m_progress, NULL, LV_PART_KNOB);
    lv_obj_set_style_arc_width(m_progress, 3, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(m_progress, lv_color_make(0, 120, 255), LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(m_progress, 3, LV_PART_MAIN);
    lv_obj_set_style_arc_color(m_progress, lv_color_make(230, 230, 230), LV_PART_MAIN);
    lv_obj_clear_flag(m_progress, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(m_progress, LV_OBJ_FLAG_HIDDEN);
}

void MainWindow::createContentArea()
{
    /* Web content area */
    m_webview = new WebView(m_bg);
    m_webview->create(CONTENT_X, CONTENT_Y, CONTENT_WIDTH, CONTENT_HEIGHT);
}

void MainWindow::createNavButtons()
{
    /* Bottom navigation: back / reload / forward */
    int btn_y = SCREEN_HEIGHT - CONTENT_MARGIN - NAV_BTN_SIZE - 5;
    int center_x = SCREEN_WIDTH / 2;
    int spacing = NAV_BTN_SIZE + 20;

    /* Back button */
    m_btn_back = lv_button_create(m_bg);
    lv_obj_set_size(m_btn_back, NAV_BTN_SIZE, NAV_BTN_SIZE);
    lv_obj_set_pos(m_btn_back, center_x - spacing - NAV_BTN_SIZE / 2, btn_y);
    lv_obj_set_style_radius(m_btn_back, NAV_BTN_SIZE / 2, 0);
    lv_obj_t* lbl_back = lv_label_create(m_btn_back);
    lv_label_set_text(lbl_back, LV_SYMBOL_LEFT);
    lv_obj_center(lbl_back);
    lv_obj_add_event_cb(m_btn_back, on_back_click, LV_EVENT_CLICKED, this);

    /* Reload button */
    m_btn_reload = lv_button_create(m_bg);
    lv_obj_set_size(m_btn_reload, NAV_BTN_SIZE, NAV_BTN_SIZE);
    lv_obj_set_pos(m_btn_reload, center_x - NAV_BTN_SIZE / 2, btn_y);
    lv_obj_set_style_radius(m_btn_reload, NAV_BTN_SIZE / 2, 0);
    lv_obj_t* lbl_reload = lv_label_create(m_btn_reload);
    lv_label_set_text(lbl_reload, LV_SYMBOL_REFRESH);
    lv_obj_center(lbl_reload);
    lv_obj_add_event_cb(m_btn_reload, on_reload_click, LV_EVENT_CLICKED, this);

    /* Forward button */
    m_btn_forward = lv_button_create(m_bg);
    lv_obj_set_size(m_btn_forward, NAV_BTN_SIZE, NAV_BTN_SIZE);
    lv_obj_set_pos(m_btn_forward, center_x + spacing - NAV_BTN_SIZE / 2, btn_y);
    lv_obj_set_style_radius(m_btn_forward, NAV_BTN_SIZE / 2, 0);
    lv_obj_t* lbl_fwd = lv_label_create(m_btn_forward);
    lv_label_set_text(lbl_fwd, LV_SYMBOL_RIGHT);
    lv_obj_center(lbl_fwd);
    lv_obj_add_event_cb(m_btn_forward, on_forward_click, LV_EVENT_CLICKED, this);
}

void MainWindow::loadUrl(const char* url)
{
    if (m_webview)
        m_webview->loadUrl(url);
    if (m_addr_bar)
        lv_textarea_set_text(m_addr_bar, url);
}

/* Event handlers */
void MainWindow::on_addr_submit(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    const char* text = lv_textarea_get_text(self->m_addr_bar);
    if (text && text[0])
        self->m_webview->loadUrl(text);
}

void MainWindow::on_back_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->goBack();
}

void MainWindow::on_forward_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->goForward();
}

void MainWindow::on_reload_click(lv_event_t* e)
{
    MainWindow* self = (MainWindow*)lv_event_get_user_data(e);
    self->m_webview->reload();
}

