#include "config.h"
#include "lvgl.h"
#include "timer.h"
#include "timer_qt5.h"

void TimerImpl::start(unsigned int ms, void* d)
{
    stop();
    m_data = d;
    m_lv_timer = lv_timer_create(lv_timer_cb, ms, this);
}

void TimerImpl::stop(void)
{
    if (m_lv_timer) {
        lv_timer_delete(m_lv_timer);
        m_lv_timer = nullptr;
    }
}

void TimerImpl::OnTimer(void)
{
    m_timer->OnTimer(m_data);
}

void TimerImpl::lv_timer_cb(lv_timer_t* t)
{
    TimerImpl* self = (TimerImpl*)lv_timer_get_user_data(t);
    self->OnTimer();
}

