class TimerImpl {
public:
    TimerImpl(Timer* t) : m_timer(t), m_lv_timer(nullptr), m_data(nullptr) {}
    ~TimerImpl() { stop(); }

    void start(unsigned int ms, void* d) {
        stop();
        m_data = d;
        m_lv_timer = lv_timer_create(lv_timer_cb, ms, this);
    }

    void stop(void) {
