    p->setWidth(104 * b);

    bool full = Application::getInstance()->getMainWindow()->getTabs()->isFullMode();

    if (menu->type & MENU_TYPE_LINK) {
        if (full) {
            height += TOOLBAR_HEIGHT;
        } else {
            height += TOOLBAR_HEIGHT * 3;
        }
        p->setLinkText(std::string(menu->link_url));
