    if (menu->type & MENU_TYPE_IMAGE) {
        if (full) {
            height += TOOLBAR_HEIGHT;
        } else {
            height += TOOLBAR_HEIGHT * 3;
        }
        p->setImgLinkText(std::string(menu->image_url));
    }

    if (full) {
        p->setWidth(80 * b);
        p->setEasyMode(true);
    } else {
        p->setEasyMode(false);
    }

    p->setHeight(height);
    p->create();
    p->Show();
}

