/* main.cpp - WatchWeb entry point
 * Copyright (C) 2026 Zhang Ji Peng <onecoolx@gmail.com>
 */
#define SDL_MAIN_HANDLED
#include "lvgl.h"
#include "macross.h"
#include "webview.h"
#include "ui.h"
#include "config.h"

static WebView g_webview;
static WatchUI g_ui;

static void on_webview_update(void* ctx)
{
    g_ui.updateCanvas();
}

static void on_webview_state(void* ctx)
{
    g_ui.updateProgress(g_webview.progress(), g_webview.isLoading());
    g_ui.updateUrl(g_webview.url());
}

static void engine_timer_cb(lv_timer_t* t)
{
    (void)t;
    macross_event_dispatch();
}

int main(int argc, char** argv)
{
    /* Init LVGL */
    lv_init();
    lv_sdl_window_create(SCREEN_WIDTH, SCREEN_HEIGHT);
    lv_sdl_mouse_create();
    lv_sdl_keyboard_create();

    /* Init Agave engine */
    macross_initialize(PIXEL_FORMAT_BGRA32, SCREEN_WIDTH, SCREEN_HEIGHT);

    /* Setup callbacks */
    MC_CALLBACK_INFO cb = {};
    cb.cb_invalidate_rect = WebView::s_dirty;
    cb.cb_update_view = WebView::s_update;
    cb.cb_loading_progress = WebView::s_loading;
    cb.cb_set_title = WebView::s_title;
    cb.cb_set_location = WebView::s_url;
    macross_set_callback(&cb);

    /* Create webview */
    g_webview.create(CONTENT_WIDTH, CONTENT_HEIGHT);
    g_webview.setUpdateCb(on_webview_update, nullptr);
    g_webview.setStateCb(on_webview_state, nullptr);

    /* Create UI */
    g_ui.create(&g_webview);

    /* Load URL */
    const char* url = (argc > 1) ? argv[1] : "https://www.baidu.com";
    g_webview.loadUrl(url);
    g_ui.updateUrl(url);

    /* Engine dispatch timer */
    lv_timer_create(engine_timer_cb, 16, nullptr);

    /* Main loop */
    while (1) {
        uint32_t ms = lv_timer_handler();
        lv_delay_ms(ms < 5 ? 5 : ms);
    }

    macross_shutdown();
    return 0;
}

